from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandTimeout
import re
import time
import six
import abc
import datetime

__author__ = 'Bartosz Odziomek, Marcin Usielski'
__copyright__ = 'Copyright (C) 2019-2020, Nokia'
__email__ = 'bartosz.odziomeki@nokia.com, marcin.usielski@nokia.com'


@six.add_metaclass(abc.ABCMeta)
class GenericEPCSIMCommand(CommandTextualGeneric):
    """GenericEPCSIMCommand command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Initialize generic for all epcsim commands.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericEPCSIMCommand, self).__init__(connection, prompt=prompt, newline_chars=newline_chars,
                                                   runner=runner)
        self.life_status.inactivity_timeout = 2.0  # Time in seconds to wait after prompt for new data from command
        # output. If no new data comes then command is finished.
        self.send_prompt_on_timeout = True  # If set_exception with CommandTimeout is set then try to send prompt (if
        # stored).
        self._last_time_incoming_data = None  # Time when last time data_received was called.
        self._last_removed_prompt = None
        self._last_time_removed_prompt = None

    def data_received(self, data, recv_time):
        """
        Call by framework when any data are sent by device.

        :param data: String (may contain new line chars) sent by device.
        :param recv_time: time stamp with the moment when the data was read from connection.  Time is given as
         datetime.datetime instance.
        :return: None.
        """
        self._last_time_incoming_data = time.monotonic()
        data_without_special_chars = GenericEPCSIMCommand._remove_chars_from_vt100_terminal(data=data)
        data_without_prompt = self._remove_candidate_for_prompt(data=data_without_special_chars)
        return super(GenericEPCSIMCommand, self).data_received(data=data_without_prompt, recv_time=recv_time)

    def set_exception(self, exception):
        """
        Set exception object as failure for command object.

        :param exception: An exception object to set. If CommandTimeout and prompt is stored then it can be passed
        to the command.
        :return: None.
        """
        if self.send_prompt_on_timeout and self._last_removed_prompt is not None and type(exception) is CommandTimeout:
            last_removed_prompt = self._last_removed_prompt
            self._last_removed_prompt = None
            super(GenericEPCSIMCommand, self).data_received(data=last_removed_prompt, recv_time=datetime.datetime.now())
            if self.done():
                return
        super(GenericEPCSIMCommand, self).set_exception(exception=exception)

    def _decode_line(self, line):
        """
        Delete new line chars and other chars we do not need to parse in on_new_line (color escape character).

        :param line: Line with special chars, raw string from device
        :return: line without special chars.
        """
        line = GenericEPCSIMCommand._remove_chars_from_vt100_terminal(data=line)
        return line

    def _process_line_from_command(self, current_chunk, line, is_full_line):
        """
        Process line from command.

        :param current_chunk: Chunk of line sent by connection.
        :param line: Line of output (current_chunk plus previous chunks of this line - if any) without newline char(s).
        :param is_full_line: True if line had newline char(s). False otherwise.
        :return: None.
        """
        decoded_line = self._decode_line(line=line)
        decoded_lines = decoded_line.splitlines(True)
        if len(decoded_lines) > 1:
            self._process_multiple_lines_decoded(decoded_lines=decoded_lines)
        else:
            self.on_new_line(line=decoded_line, is_full_line=is_full_line)

    def _process_multiple_lines_decoded(self, decoded_lines):
        """
        Process line from command with decoded new line chars from output.

        :param decoded_lines: list od decode lines.
        :return: None.
        """
        line_nr = 0
        # all line except last one
        while line_nr < len(decoded_lines) - 1:
            double_decoded_line = decoded_lines[line_nr]
            self.on_new_line(line=double_decoded_line, is_full_line=True)
            line_nr += 1
        # last line
        self._last_not_full_line = None
        last_line, is_full_line_double_decoded = self._update_from_cached_incomplete_line(
            current_chunk=decoded_lines[line_nr])
        self.on_new_line(line=last_line, is_full_line=is_full_line_double_decoded)

    def _remove_candidate_for_prompt(self, data):
        """
        Remove prompt from data.

        :param data: data from connection.
        :return: data without prompt.
        """
        lines = data.splitlines(True)
        new_data = ""
        for line in lines:
            m = re.search(self._re_prompt, line)
            if m:
                self._last_removed_prompt = m.group(0)
                line = re.sub(self._re_prompt, "", line)
                new_data += line  # Line has optional new line chars
                self._last_time_removed_prompt = self._last_time_incoming_data
            else:
                new_data += line  # Line has optional new line chars
                self._last_removed_prompt = None
                self._last_time_removed_prompt = None

        return new_data

    def on_inactivity(self):
        """
        Call when no data is received on connection within self.life_status.inactivity_timeout seconds.

        :return: None
        """
        if self._last_removed_prompt is not None:
            last_removed_prompt = self._last_removed_prompt
            self._last_removed_prompt = None
            return super(GenericEPCSIMCommand, self).data_received(data=last_removed_prompt,
                                                                   recv_time=datetime.datetime.now())

    # CRLF 2 LF
    _re_crlf_2_lf = re.compile(chr(0x0D) + chr(0x0A))

    # 0 bytes
    _re_0_byte = re.compile(chr(0))

    # remove colors
    _re_colors_remove = re.compile(f"{chr(27)}\\[[\\d;]+m")

    # remove spaces from status line
    _re_spaces_from_status_line = re.compile(r"(UEs configured: \d+\|active: \d+\|idle: \d+)(\s+)")

    # remove status line in 4 cases:
    _re_status_line_1 = re.compile("".join([chr(0x1B), r"\[\d*D", chr(0x1B),
                                            r"\[\d*BUEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+",
                                            chr(0x0D), chr(0x1B), r"\[\d*C", chr(0x1B), r"\[\d*A"]))
    _re_status_line_2 = re.compile("".join([chr(0x1B), r"\[\d*BUEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+",
                                            chr(0x0D), chr(0x1B), r"\[\d*A"]))
    _re_status_line_3 = re.compile("".join([chr(0x0A), r"UEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+",
                                            chr(0x0D), r"(", chr(0x1B), r"\[A", chr(0x1B), r"\[K|",
                                            chr(0x1B), r"\[A)"]))
    _re_status_line_4 = re.compile("".join([r"UEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+", chr(0x0D),
                                            r"(", chr(0x1B), r"\[A", chr(0x1B), r"\[K|", chr(0x1B), r"\[A)"]))

    # cursor up N lines and clear
    _re_cursor_up_n_lines_and_clear = re.compile(f"{chr(27)}\\[\\d+A{chr(27)}c{chr(27)}\\[\\d+B")

    # cursor down N lines and clear
    _re_cursor_down_n_lines_and_clear = re.compile(f"{chr(27)}\\[\\d+B{chr(27)}\\[K{chr(27)}\\[\\d+A")

    # cursor down
    _re_cursor_down = re.compile(f"{chr(27)}\\[\\d+B")

    # cursor up
    _re_cursor_up = re.compile(f"{chr(27)}\\[\\d+A")

    # clear to end of line
    _re_clear_to_end_of_line = re.compile(f"{chr(10) + chr(27)}\\[K")

    # cursor back plus cursor forward
    _re_cursor_back_and_forward = re.compile(f"{chr(27)}\\[D{chr(27)}\\[C")

    # prompt + clear prompt + clear to end of line
    _re_prompt_clear_to_end_of_line = re.compile(r"EGATE> " + chr(0x1B) + r"\[7D" + chr(0x1B) + r"\[K")

    # clear prompt + clear tp end of line
    _re_clear_prompt_and_to_end_of_line = re.compile(r"^" + chr(0x1B) + r"\[7D" + chr(0x1B) + r"\[K")

    # clear at start and to the end of line
    _re_clear_at_start_to_end_of_line = re.compile(r"^" + chr(0x1B) + r"\[K")

    @classmethod
    def _remove_chars_from_vt100_terminal(cls, data):
        """
        Remove chars for vt100 terminal.

        :param data: Input string with additional control chars.
        :return: String without control chars. However may contain new line chars .
        """
        # CRLF 2 LF
        data = re.sub(cls._re_crlf_2_lf, chr(0x0A), data)

        # remove "zero" bytes
        data = re.sub(cls._re_0_byte, "", data)

        # remove colors
        # $vt100_cmds = ~ s /\x1B\[[\d;]+m//g;
        data = re.sub(cls._re_colors_remove, "", data)

        # remove spaces from status line
        # $vt100_cmds =~ s/(UEs configured: \d+\|active: \d+\|idle: \d+)(\s+)/$1/g;
        data = re.sub(cls._re_spaces_from_status_line, r'\g<1>', data)

        # remove status line
        # $vt100_cmds =~ s/\x1B\[\d*D\x1B\[\d*BUEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+\x0D\x1B\[\d*C\x1B\[\d*A//g;
        # $vt100_cmds =~ s/\x1B\[\d*BUEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+\x0D\x1B\[\d*A//g;
        # $vt100_cmds =~ s/\x0AUEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+\x0D(\x1B\[A\x1B\[K|\x1B\[A)//g;
        # $vt100_cmds =~ s/UEs configured: \d+\|active: \d+\|idle: \d+\s*\|\w+\x0D(\x1B\[A\x1B\[K|\x1B\[A)//g;
        data = re.sub(cls._re_status_line_1, "", data)
        data = re.sub(cls._re_status_line_2, "", data)
        data = re.sub(cls._re_status_line_3, "", data)
        data = re.sub(cls._re_status_line_4, "", data)

        # remove cursors:
        #  # Cursor Up N lines + terminal reset(clear) + Cursor Down N lines to single \n
        #     $vt100_cmds =~ s/\x1B\[\d+A\x1Bc\x1B\[\d+B/\n/g;
        #     $self->debug_data(-LINE => $vt100_cmds, -STAGE => 'up-reset-down 2 nl');
        #
        #     # Cursor Down N lines + clear line till end + Cursor Up N lines to single \n
        #     $vt100_cmds =~ s/\x1B\[\d+B\x1B\[K\x1B\[\d+A/\n/g;
        #     $self->debug_data(-LINE => $vt100_cmds, -STAGE => 'down-lnClear-up 2 nl');
        data = re.sub(cls._re_cursor_up_n_lines_and_clear, "\n", data)
        data = re.sub(cls._re_cursor_down_n_lines_and_clear, "\n", data)

        # # Cursor Down N lines to single \n
        #     $vt100_cmds =~ s/\x1B\[\d+B/\n/g;
        #     $self->debug_data(-LINE => $vt100_cmds, -STAGE => 'n lines down 2 nl');
        #
        #     # Cursor Up N lines to single \n
        #     $vt100_cmds =~ s/\x1B\[\d+A/\n/g;
        #     $self->debug_data(-LINE => $vt100_cmds, -STAGE => 'n lines down 2 nl');
        data = re.sub(cls._re_cursor_down, "\n", data)
        data = re.sub(cls._re_cursor_up, "\n", data)

        # # \n + clear to end of line --> \n
        #     $vt100_cmds =~ s/\x0A\x1B\[K/\n/g;
        data = re.sub(cls._re_clear_to_end_of_line, "\n", data)

        # # Cursor Back 1 + Cursor Forward 1 == nothing
        #     $vt100_cmds =~ s/\x1B\[D\x1B\[C//g;
        data = re.sub(cls._re_cursor_back_and_forward, "", data)

        #     # prompt + clear prompt + clear to end of line --> nothing
        #     $vt100_cmds =~ s/EGATE> \x1B\[7D\x1B\[K//g;
        data = re.sub(cls._re_prompt_clear_to_end_of_line, "", data)

        #     # clear prompt at start + clear to end of line --> nothing
        #     $vt100_cmds =~ s/^\x1B\[7D\x1B\[K//g;
        data = re.sub(cls._re_clear_prompt_and_to_end_of_line, "", data)

        #     # at start  clear to end of line --> nothing
        #     $vt100_cmds =~ s/^\x1B\[K//g;
        data = re.sub(cls._re_clear_at_start_to_end_of_line, "", data)

        #
        #     # CR 2 LF
        #     $vt100_cmds =~ s/\x0d/\x0a/g;
        #     $self->debug_data(-LINE => $vt100_cmds, -STAGE => 'CR 2 LF');
        data = re.sub(cls._re_crlf_2_lf, chr(0x0A), data)

        return data
